using P=SmPoint3d;using V=SmVector3d;
static std::string run_dir;
static void save(const std::string& name,const Json& j){std::ofstream f(run_dir+"/"+name);f<<j.dump()<<"\n";f.flush();}
static void phase(const std::string&s){Json j=Json::object();j["stage"]=s;save("phase.json",j);std::cout<<"stage="<<s<<std::endl;}
static Json arr(std::initializer_list<double> xs){Json j=Json::array();for(double x:xs)j.push(x);return j;}
static Json xyz(const V&p){return arr({p.x,p.y,p.z});}
static Json uvjson(const SmPoint2d&p){return arr({p.x,p.y});}
static double dist(const P&a,const P&b){return std::sqrt((a.x-b.x)*(a.x-b.x)+(a.y-b.y)*(a.y-b.y)+(a.z-b.z)*(a.z-b.z));}
static V cross(const V&a,const V&b){return V(a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x);}
static double dot(const V&a,const V&b){return a.x*b.x+a.y*b.y+a.z*b.z;}
static double norm(const V&a){return std::sqrt(dot(a,a));}
static V unit(V a){double l=norm(a);return l>1e-20?a/l:V(0,0,0);}
static double segdist(const P&p,const P&a,const P&b){V d=b-a;double t=dot(p-a,d)/std::max(dot(d,d),1e-30);t=std::max(0.,std::min(1.,t));return dist(p,a+d*t);}
struct Target{std::string id,kind;int expected_count=1;double tol=1e-6,coverage=1e-5,length=-1;P center;V normal;double radius=0,span=0;std::vector<P> samples;};
struct Config{std::string input,kind;double radius=0,start=0,end=0;bool variable=false;int xsect=1,continuity=1;double thumb=1;std::vector<Target> targets;std::vector<std::pair<std::string,P>> protected_probes;};
static Config config(const char*path){Config c;std::ifstream f(path);std::string token;int n;f>>token>>std::quoted(run_dir);if(token!="RUN_DIR")throw std::runtime_error("bad RUN_DIR");f>>token>>std::quoted(c.input);f>>token>>c.kind;f>>token>>c.radius;f>>token>>c.variable>>c.start>>c.end;f>>token>>c.xsect>>c.continuity>>c.thumb;f>>token>>n;if(token!="TARGETS")throw std::runtime_error("bad TARGETS");for(int k=0;k<n;++k){Target t;int m;f>>token>>std::quoted(t.id)>>t.kind>>t.expected_count>>t.tol>>t.coverage>>t.length>>t.center.x>>t.center.y>>t.center.z>>t.normal.x>>t.normal.y>>t.normal.z>>t.radius>>t.span>>m;for(int i=0;i<m;++i){P p;f>>p.x>>p.y>>p.z;t.samples.push_back(p);}if(t.samples.size()<2)throw std::runtime_error("target needs at least two samples");c.targets.push_back(t);}f>>token>>n;for(int i=0;i<n;++i){std::string id;P p;f>>std::quoted(id)>>p.x>>p.y>>p.z;c.protected_probes.push_back({id,p});}if(!f)throw std::runtime_error("truncated tokens");return c;}
static double targetdist(const Target&t,const P&p){
 if(t.kind=="line")return segdist(p,t.samples.front(),t.samples.back());
 if(t.kind=="circle"){
  V n=unit(t.normal),v=p-t.center;double axial=dot(v,n);V flat=v-n*axial;double radial=norm(flat);double d=std::hypot(axial,radial-t.radius);
  if(t.span>=2*M_PI-1e-6)return d;V x=unit(t.samples.front()-t.center),y=cross(n,x);double a=std::atan2(dot(flat,y),dot(flat,x));if(a<0)a+=2*M_PI;if(a<=t.span+1e-8)return d;return std::min(dist(p,t.samples.front()),dist(p,t.samples.back()));
 }
 double d=1e100;for(size_t i=1;i<t.samples.size();++i)d=std::min(d,segdist(p,t.samples[i-1],t.samples[i]));return d;
}
static bool drop(SmEdge*e,const P&p,double tol,double&d,double*param=nullptr){SmBoolean success=FALSE;double t=0;d=1e100;auto st=e->GetCurve()->DropPoint(e->GetInterval(),p,nullptr,tol,nullptr,success,t,d,SM_SO_MINIMIZE);if(param)*param=t;return st==SM_SUCCESS&&success&&std::isfinite(d);}
static std::vector<P> edgepoints(SmEdge*e,int count=65){std::vector<P> a;auto d=e->GetInterval();for(int i=0;i<count;++i){P p;if(e->GetCurve()&&e->GetCurve()->EvaluatePoint(d.GetMin()+(d.GetMax()-d.GetMin())*i/(count-1.),p)==SM_SUCCESS)a.push_back(p);}return a;}
static Json pointarray(const std::vector<P>&a){Json j=Json::array();for(auto&p:a)j.push(xyz(p));return j;}
static SmFaceuse* oriented_use(SmFace*f,bool&certified){SmFaceuse*a=nullptr,*b=nullptr;f->GetFaceuses(a,b);certified=false;for(auto*x:{a,b})if(x&&x->GetRegion()&&!x->GetRegion()->IsVoid()){certified=true;return x;}return f->GetUpwardFaceuse();}
