static bool jb(const Json&j,const std::string&k){auto&m=std::get<Json::Obj>(j.v);auto at=m.find(k);if(at==m.end()||!std::holds_alternative<bool>(at->second.v))return false;return std::get<bool>(at->second.v);}
static double jd(const Json&j,const std::string&k,double fallback=0){auto&m=std::get<Json::Obj>(j.v);auto at=m.find(k);if(at==m.end()||!std::holds_alternative<double>(at->second.v))return fallback;return std::get<double>(at->second.v);}
